PHASE="8b-smoke"; say "8b. Smoke test baca-saja: izin catat status kerja, membuka pekerjaan tidak menulis, tak ada jejak tulis (stok/Run/QC/jurnal/jadwal/target/Bendrya)"
# shellcheck disable=SC1090
. "$BK_DIR/garis-dasar.env"
dcp "$NEW_DIR" exec -T -e BASE_TIDAK_SEIMBANG="$BASE_TIDAK_SEIMBANG" -e BASE_GANDA="$BASE_GANDA" -e ORDER_N="$ORDER_N" -e JOB_N="$JOB_N" backend node --input-type=module - <<'NODE' | tee "$BK_DIR/smoke.log" || die "smoke test GAGAL"
import { createRequire } from "node:module";
const require = createRequire(process.cwd() + "/");
const jwt = require("jsonwebtoken");
const { PrismaClient } = require("@prisma/client");
const prisma = new PrismaClient();
const BASE = "http://127.0.0.1:4000";
let fail = 0; let dilewati = 0;
const rec = (n, ok, d = "") => { if (!ok) fail++; console.log(`  ${ok ? "PASS" : "FAIL"}  ${n}${d ? " — " + d : ""}`); };
const skip = (n, alasan) => { dilewati++; console.log(`  SKIP  ${n} — DILEWATI: ${alasan}`); };
const D = await import("/app/src/lib/domain/productionWorkStatus.js");
const rolesDari = async (u) => new Set([u.role, ...(await prisma.userRole.findMany({ where: { userId: u.id }, select: { role: true } })).map((r) => r.role)]);
const tokenUntuk = async (u) => jwt.sign({ id: u.id, name: u.name, role: u.role, roles: [...(await rolesDari(u))] }, process.env.JWT_SECRET, { expiresIn: "10m" });
const BERIZIN = new Set(["ADMIN", "OWNER", "FINANCE", "ACCOUNTANT", "APPROVER", "PRODUCTION_LEAD"]);
async function userDengan(role, tanpa) {
  for (const u of await prisma.user.findMany({ where: { active: true } })) { const rs = await rolesDari(u); if (rs.has(role) && ![...rs].some((r) => tanpa.has(r))) return u; }
  return null;
}
const adm = (await userDengan("ADMIN", new Set())) ?? (await userDengan("OWNER", new Set()));
const sales = await userDengan("SALES", BERIZIN);
if (!adm) { rec("akun ADMIN tersedia", false); process.exit(1); }
const tA = await tokenUntuk(adm); const tS = sales ? await tokenUntuk(sales) : null;
const hitung = async (q) => Number((await prisma.$queryRawUnsafe(q))[0].n);
const B = (k) => Number(process.env[k]);
const get = async (path, token) => { const r = await fetch(BASE + path, { headers: token ? { Authorization: "Bearer " + token } : {} }); let j = null; try { j = await r.json(); } catch { /* bukan JSON */ } return { status: r.status, json: j }; };
const post = (path, token) => fetch(BASE + path, { method: "POST", headers: { "Content-Type": "application/json", ...(token ? { Authorization: "Bearer " + token } : {}) }, body: "{}" });
const TABEL = ["stock_movements", "production_runs_v2", "production_run_plans_v2", "qc_fit_tests", "fin_journal_entries", "fin_journal_lines", "production_unit_schedules", "production_unit_schedule_events", "units", "production_unit_work_progress", "activity_events"];
const fp = async () => { const o = {}; for (const t of TABEL) o[t] = (await prisma.$queryRawUnsafe(`select count(*)::int n, coalesce(md5(string_agg(x::text, '|' order by x::text)),'') h from "${t}" x`))[0]; return o; };
const ub = await prisma.unit.findFirst({ where: { unitCode: "RES-19102026-094-U1" }, select: { id: true } });
const snapBendrya = async () => ub ? JSON.stringify([await prisma.unit.findUnique({ where: { id: ub.id }, select: { id: true, status: true, productionDueAt: true, updatedAt: true } }), await prisma.productionUnitSchedule.findMany({ where: { unitId: ub.id }, orderBy: { id: "asc" } }), await prisma.productionUnitScheduleEvent.findMany({ where: { unitId: ub.id }, orderBy: { id: "asc" } }), await prisma.productionUnitWorkProgress.count({ where: { unitId: ub.id } })]) : "tidak-ada";
const sebelum = await fp(); const bSebelum = await snapBendrya();

// kode yang berjalan = kode kandidat
const dj = D.tindakanBerikutnya({ unitStatus: "RECEIVED", posisi: { key: "DI_WORKSHOP" }, kerja: { key: "DIJADWALKAN" } });
rec("kode berjalan: Dijadwalkan → OPEN_WORK 'Buka pekerjaan'; tidak ada START_WORK", dj.aksi === "OPEN_WORK" && dj.label === "Buka pekerjaan" && !("START_WORK" in D.AKSI));
rec("kode berjalan: FINISH_WORK berlabel 'Catat pekerjaan selesai'", D.tindakanBerikutnya({ unitStatus: "RECEIVED", posisi: { key: "DI_WORKSHOP" }, kerja: { key: "DIKERJAKAN" }, aktualAda: true }).label === "Catat pekerjaan selesai");

// izin (ditolak SEBELUM menyentuh data)
const ID0 = "00000000-0000-4000-8000-000000000000";
rec("catat status kerja: tanpa token 401", (await post(`/api/production/units/${ID0}/work-progress`, null)).status === 401);
if (tS) rec("catat status kerja: SALES (hanya-lihat) 403", (await post(`/api/production/units/${ID0}/work-progress`, tS)).status === 403);
else skip("catat status kerja: SALES 403", "tidak ada akun SALES murni aktif (diuji di tes integrasi)");
if (tS) rec("SALES tetap boleh MEMBUKA daftar kerja (membuka = baca)", (await get("/api/production/work-list?scope=aktif&pageSize=5", tS)).status === 200);

// membuka pekerjaan = baca-saja: daftar + tindakan + detail unit (dua kali) pada data produksi
const wl = await get("/api/production/work-list?scope=aktif&pageSize=100", tA);
rec("daftar kerja (Admin) 200", wl.status === 200, String(wl.status));
const teks = JSON.stringify(wl.json ?? {});
rec("daftar kerja produksi: tidak memuat 'Mulai pekerjaan' / START_WORK", !/Mulai pekerjaan|START_WORK/.test(teks));
const orders = wl.json?.orders ?? [];
const unitDj = orders.flatMap((o) => o.units.map((u) => ({ ...u, order: o }))).find((u) => u.kerja?.key === "DIJADWALKAN");
console.log(`  INFO  order aktif: ${orders.length}; unit Dijadwalkan: ${orders.flatMap((o) => o.units).filter((u) => u.kerja?.key === "DIJADWALKAN").length}`);
if (!unitDj) skip("unit Dijadwalkan: detail 'Buka pekerjaan' dua kali identik", "tidak ada unit Dijadwalkan saat ini (diuji di tes integrasi dan rehearsal salinan)");
else {
  const a1 = await get(`/api/production/units/${unitDj.id}/adopsi`, tA); const a2 = await get(`/api/production/units/${unitDj.id}/adopsi`, tA); await get(`/api/production/units/${unitDj.id}/ruang-kerja`, tA);
  rec(`unit Dijadwalkan ${unitDj.unitCode}: detail 200; tindakan berikutnya tidak menulis (dua pembacaan identik)`, a1.status === 200 && a2.status === 200 && JSON.stringify(a1.json.adopsi.kerja) === JSON.stringify(a2.json.adopsi.kerja) && a1.json.kerjaManual.riwayat.length === a2.json.kerjaManual.riwayat.length, `${a1.json?.adopsi?.tindakan?.aksi}`);
  rec("tindakan unit Dijadwalkan (sudah diterima): OPEN_WORK 'Buka pekerjaan' (atau tindakan lain yang sah bila belum diterima), bukan START_WORK", a1.json.adopsi.tindakan.aksi !== "START_WORK" && (a1.json.adopsi.tindakan.aksi !== "OPEN_WORK" || a1.json.adopsi.tindakan.label === "Buka pekerjaan"), `${a1.json.adopsi.tindakan.aksi} / ${a1.json.adopsi.tindakan.label}`);
}

// tak ada jejak tulis: stok, Run, QC, jurnal, jadwal, target (units), catatan kerja, audit
const sesudah = await fp(); const beda = TABEL.filter((t) => sebelum[t].n !== sesudah[t].n || sebelum[t].h !== sesudah[t].h);
rec("TIDAK ada jejak tulis: stok, Run, rencana Meja, QC, jurnal, jadwal, riwayat jadwal, unit/target, catatan kerja, dan audit sama persis sebelum vs sesudah smoke", beda.length === 0, beda.join(",") || "identik");
rec("jadwal + target unit Bendrya (RES-19102026-094-U1) tidak berubah", (await snapBendrya()) === bSebelum, ub ? "diperiksa" : "unit tidak ditemukan — dilewati");
rec("jurnal tidak seimbang (sebelum rilis: " + B("BASE_TIDAK_SEIMBANG") + ", tidak bertambah)", (await hitung("select count(*)::int n from (select e.id from fin_journal_entries e join fin_journal_lines l on l.entry_id = e.id group by e.id having sum(l.debit) <> sum(l.credit)) x")) <= B("BASE_TIDAK_SEIMBANG"));
rec("jumlah Order & Job tidak berkurang (sebelum: " + B("ORDER_N") + " / " + B("JOB_N") + ")", (await hitung('select count(*)::int n from "Order"')) >= B("ORDER_N") && (await hitung("select count(*)::int n from jobs")) >= B("JOB_N"));
await prisma.$disconnect();
console.log("\nRINGKASAN smoke: " + fail + " gagal, " + dilewati + " dilewati (SKIP)");
console.log("SMOKE_HASIL fail=" + fail + " skip=" + dilewati);
process.exit(fail ? 1 : 0);
NODE
SMOKE_LINE="$(grep '^SMOKE_HASIL ' "$BK_DIR/smoke.log" | tail -n 1)"
SMOKE_SKIP="$(printf '%s' "$SMOKE_LINE" | sed -n 's/^SMOKE_HASIL fail=0 skip=\([0-9][0-9]*\)$/\1/p')"
[ -n "$SMOKE_SKIP" ] || die "smoke test tidak mencetak ringkasan SMOKE_HASIL yang lulus (jangan anggap lulus)"
if [ "$SMOKE_SKIP" != "0" ]; then
  warn "smoke test lulus dengan ${SMOKE_SKIP} pemeriksaan DILEWATI (SKIP): lihat alasan di ${BK_DIR}/smoke.log. Ini BUKAN PASS untuk pemeriksaan yang dilewati."
else
  ok "smoke test lulus (izin, membuka pekerjaan baca-saja, tanpa jejak tulis, jadwal+target Bendrya utuh, invarian)"
fi
OLD_ONLY="$(sed -n 1p "$OLD_ASSETS" || true)"
if [ -n "$OLD_ONLY" ]; then
  [ "$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 "${PUBLIC_URL}/assets/${OLD_ONLY}")" = "200" ] || die "aset lama /assets/${OLD_ONLY} tidak bisa diunduh (404) — pembawaan aset lama gagal"
  ok "aset lama ${OLD_ONLY} masih 200 (tab terbuka tidak kena 404)"
fi
[ "$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 "${PUBLIC_URL}/assets/tidak-ada-zz.js")" = "404" ] || die "aset yang memang tidak ada harus 404 jujur"
ok "aset yang tidak ada = 404 (bukan index.html)"
sleep 20
[ "$(docker inspect -f '{{.RestartCount}}' "$CID_NEW")" = "0" ] || die "backend restart sendiri setelah switch"
[ "$(docker inspect -f '{{.State.Running}}' "$CID_NEW")" = "true" ] || die "backend tidak berjalan"
ok "backend stabil: RestartCount=0 setelah 20 detik"
dcp "$NEW_DIR" exec -T postgres psql -U "$DB_USER" -d "$DB_NAME" -X -At -q -c "$FP_BEKU_SQL" </dev/null | LC_ALL=C sort > "$BK_DIR/data-sesudah.txt" || die "sidik jari dokumen beku sesudah gagal"
diff "$BK_DIR/data-sebelum.txt" "$BK_DIR/data-sesudah.txt" >/dev/null || { diff "$BK_DIR/data-sebelum.txt" "$BK_DIR/data-sesudah.txt" || true; die "dokumen PEMBANDING (beku sebelum switch) BERUBAH selama rilis — periksa dengan backup"; }
ok "dokumen pembanding beku (refund & pengeluaran final, baris jurnal, saldo per akun, pembayaran, PKR/unit final, muat, flag) IDENTIK sebelum vs sesudah rilis; transaksi sah yang muncul saat rilis tidak diperbandingkan"
# Pembersihan release lama (setelah rilis TERBUKTI sehat). Dipertahankan: 4 terbaru (mtime), release baru, release sebelumnya, dan release yang dirujuk container berjalan. Kegagalan di sini TIDAK menggagalkan rilis.
PHASE="9-pembersihan"; say "9. Pembersihan release lama (menyisakan 4 terbaru + yang dipakai container)"
(
  cd "$RELEASES" || exit 0
  KEEP="$(ls -1dt */ | head -4 | tr -d /)
$(basename "$NEW_DIR")
$(basename "$PREV_DIR")"
  for c in $(docker ps -q); do w="$(docker inspect -f '{{index .Config.Labels "com.docker.compose.project.working_dir"}}' "$c" 2>/dev/null)"; [ -n "$w" ] && KEEP="$KEEP
$(basename "$w")"; done
  HAPUS="$(ls -1d */ | tr -d / | grep -vxF -f <(echo "$KEEP" | sort -u) || true)"
  n=0; for d in $HAPUS; do case "$d" in ""|"."|"..") continue;; esac; [ -d "$d" ] || continue; rm -rf -- "$d" 2>/dev/null || sudo -n rm -rf -- "$d" 2>/dev/null; n=$((n+1)); done
  echo "  OK    release lama dihapus: $n folder; disk: $(df -h "$HOME" | awk 'NR==2{print $4" bebas"}')"
) || echo "  (pembersihan dilewati)"
trap - EXIT
say "SELESAI — rilis ${DEPLOY_SHORT} aktif. Backup: ${BACKUP_FILE}. Image rollback: ${ROLLBACK_TAG}. Log: ${BK_DIR}/release.log"
say "CATATAN: Rilis ini hanya mengubah label/alur tindakan status kerja Produksi (Buka pekerjaan; Catat pekerjaan selesai dengan konfirmasi). Tidak ada catatan, jadwal, target, stok, Run, QC, atau jurnal yang dibuat/diubah oleh rilis; tanpa migrasi."
